(function(root){'use strict';
const blueprints=[{id:'trend',name:'趋势港',strategy:'趋势决策',partner:'趋势交易员·赤霄',icon:'◈',color:'#90bfea',description:'板块上涨时跟进；对应“大笔跟进”决策。',turnover:150},{id:'value',name:'价值街',strategy:'价值决策',partner:'价值买手·知夏',icon:'◇',color:'#d6b785',description:'价格跌下来时分批试买；对应“半价试买”决策。',turnover:60},{id:'defense',name:'防守园',strategy:'防守决策',partner:'现金守门员·凛川',icon:'⬡',color:'#91d8c1',description:'不确定时保留现金；对应“先不买”决策。',turnover:40},{id:'research',name:'研究院',strategy:'研究决策',partner:'研究分析师·星澜',icon:'✦',color:'#a9a0e8',description:'先花钱核对消息；对应“花钱调查”决策。',turnover:80}];
const factors=[{id:'momentum',difficulty:'R',concept:'动量因子',industry:'trend',name:'趋势·动量木材',icon:'▤',label:'趋势港专属材料',description:'给趋势港使用；行情延续时加强，反转时可能失效。'},{id:'lowvol',difficulty:'R',concept:'低波动因子',industry:'defense',name:'防守·低波钢材',icon:'▥',label:'防守园专属材料',description:'给防守园使用；降低波动但不保证赚钱。'},{id:'value',difficulty:'SR',concept:'估值因子',industry:'value',name:'价值·估值玻璃',icon:'▧',label:'价值街专属材料',description:'给价值街使用；价格便宜也可能继续下跌。'},{id:'volume',difficulty:'SSR',concept:'量价验证',industry:'research',name:'研究·量能铜线',icon:'⌁',label:'研究院专属材料',description:'给研究院使用；帮助核对消息与成交线索。'}];
function init(s){if(!s.city)s.city={version:2,cycle:0,blueprints:['trend'],materials:{momentum:2,lowvol:2,value:1,volume:1},districts:[],ledger:[],draws:[],drawn:{},pending:null,feedback:null};s.city.version=2;s.city.feedback??=null;return s.city;}
function gameDay(s){return Math.min(Game.CONFIG.days,Math.floor(s.round/Game.CONFIG.roundsPerDay)+1);}
function cycledToday(s){const day=gameDay(s);return init(s).ledger.some(x=>(x.gameDay||0)===day);}
function draw(s,pool){const c=init(s),day=gameDay(s),key=pool+'-day-'+day;if(c.drawn[key])throw Error('今天已经抽过这类卡了，明天再来');c.drawn[key]=true;let item;if(pool==='strategy'){const available=blueprints.filter(b=>!c.blueprints.includes(b.id));item=available[Math.floor(Game.rand(s.seed+day*31+782)*available.length)];if(item)c.blueprints.push(item.id);else{c.materials.lowvol++;item={name:'蓝图已齐全 · 补充低波钢材'};}}else if(pool==='factor'){const f=factors[Math.floor(Game.rand(s.seed+day*37+521)*4)];c.materials[f.id]+=2;item={name:f.name+' × 2'};}else throw Error('未知卡池');const roll=Game.rand(s.seed+day*97+(pool==='strategy'?11:23)),rarity=roll<.5?'R':roll<.85?'SR':'SSR';c.draws.push({day,pool,item:item.name,rarity});return item.name;}
function build(s,id,factorIds,budget){const c=init(s);if(!c.blueprints.includes(id)||c.districts.some(d=>d.id===id))throw Error('蓝图不可用或区域已建成');if(!s.evidence.some(e=>e.dimension==='attribute'&&e.value===id&&e.source!=='city_build'))throw Error('先在决策中获得一次同类属性，才能建设这个产业');if(!Number.isInteger(budget)||budget<100||budget>5000)throw Error('预算须为100–5000整数游戏币');if(factorIds.length<1||factorIds.length>2||new Set(factorIds).size!==factorIds.length)throw Error('选择1–2种不同材料');for(const f of factorIds)if(!factors.some(x=>x.id===f)||!c.materials[f])throw Error('材料不足');for(const f of factorIds)c.materials[f]--;const district={id,factors:[...factorIds],budget,development:12,stability:100,last:null};c.districts.push(district);c.pending=null;const blueprint=blueprints.find(b=>b.id===id),materialNames=factorIds.map(id=>factors.find(f=>f.id===id).name);c.feedback={kind:'build',title:blueprint.name+'建成',text:blueprint.strategy+' +1。你的同类决策解锁了这个产业。'};Game.evidence(s,'construction',id+'|'+factorIds.join('+')+'|'+(budget<=1000?'small':budget<=3000?'medium':'large'),'observed_action','during',false,'city-'+id);Game.evidence(s,'attribute',id,'city_build','during',false,'city-'+id);return district;}
function refit(s,id,ids,budget){const c=init(s),d=c.districts.find(d=>d.id===id);if(!d)throw Error('区域不存在');if(!Number.isInteger(budget)||budget<100||budget>5000)throw Error('预算须为100–5000整数');if(ids.length<1||ids.length>2||new Set(ids).size!==ids.length)throw Error('选择1–2种不同材料');for(const f of ids)if(!factors.some(x=>x.id===f)||(c.materials[f]||0)+(d.factors.includes(f)?1:0)<1)throw Error('材料不足');for(const f of d.factors)c.materials[f]++;for(const f of ids)c.materials[f]--;d.factors=[...ids];d.budget=budget;c.pending=null;const blueprint=blueprints.find(b=>b.id===id);c.feedback={kind:'refit',title:blueprint.name+'已调整',text:'新材料：'+ids.map(id=>factors.find(f=>f.id===id).name).join('、')+'；每日建设预算 '+budget+' 游戏币。下次领取建设收益时显示调整效果。'};Game.evidence(s,'construction',id+'|'+ids.join('+')+'|'+(budget<=1000?'small':budget<=3000?'medium':'large'),'observed_action','during',false);}
function market(seed,cycle){const x=Game.rand((seed+cycle*7919+95671)>>>0);return {seed:(seed+cycle*7919+95671)>>>0,regime:x<.34?'上行':x<.67?'震荡':'下行',basisPoints:Math.floor(x*1601)-800};}
function returns(d,m){let bp=d.id==='trend'?m.basisPoints:d.id==='value'?Math.round(m.basisPoints*.65)+80:d.id==='research'?Math.round(m.basisPoints*.5)+40:Math.round(m.basisPoints*.35);if(d.factors.includes('momentum'))bp+=m.regime==='上行'?180:-100;if(d.factors.includes('lowvol'))bp=Math.round(bp*.65);if(d.factors.includes('value'))bp+=m.regime==='震荡'?120:-40;if(d.factors.includes('volume'))bp+=m.regime==='上行'?80:-60;const turnover=blueprints.find(b=>b.id===d.id).turnover+(d.factors.length-1)*50;return {bp,turnover,fee:Math.ceil(d.budget*turnover/10000),gross:Math.floor(d.budget*bp/10000)};}
function draft(s){const c=init(s),day=gameDay(s);if(cycledToday(s))throw Error('今天已经领取过建设收益；完成今天 3 轮决策后，明天可再次领取');if(!c.districts.length)throw Error('先建设至少一个策略区域');const amount=c.districts.reduce((n,d)=>n+d.budget,0),fees=c.districts.reduce((n,d)=>n+returns(d,{basisPoints:0,regime:'震荡'}).fee,0);if(amount+fees>s.balance)throw Error('每日建设预算和运营费超过现金，请先下调区域预算');return {cycle:c.cycle,gameDay:day,key:s.id+'-city-day-'+day,amount,fees,config:JSON.stringify(c.districts.map(d=>({id:d.id,factors:d.factors,budget:d.budget}))),rule:'city-1.1'};}
function settle(s,a){const c=init(s),prior=c.ledger.find(e=>e.idempotencyKey===a.key);if(prior)return prior;const valid=draft(s);if(a.key!==valid.key||a.config!==valid.config||a.cycle!==valid.cycle||a.gameDay!==valid.gameDay)throw Error('城市方案已变化，请重新确认');const m=market(s.seed,c.cycle),before=s.balance,details=c.districts.map(d=>{const r=returns(d,m),delta=r.gross-r.fee,credit=d.budget+r.gross;d.development=Math.max(0,Math.min(100,d.development+(delta>0?Math.max(1,Math.floor(delta/10)):0)));d.stability=Math.max(0,Math.min(100,d.stability+(delta<0?-Math.ceil(Math.abs(delta)/20):2)));d.last={...r,delta,credit,cycle:c.cycle};return {id:d.id,budget:d.budget,factors:[...d.factors],development:d.development,stability:d.stability,...d.last};}),delta=details.reduce((n,d)=>n+d.delta,0);s.balance+=delta;const entry={idempotencyKey:a.key,cycle:c.cycle,gameDay:a.gameDay,market:m,rule:a.rule,proposal:a,details,balanceBefore:before,balanceAfter:s.balance,delta};c.ledger.push(entry);c.cycle++;c.pending=null;c.feedback={kind:'market',title:'第 '+a.gameDay+' 天建设收益',text:'今日市场'+m.regime+'，城区净收益 '+(delta>=0?'+':'')+delta+' 游戏币。'+details.map(d=>blueprints.find(b=>b.id===d.id).name+'：建设 '+d.development+'%，稳定 '+d.stability+'%').join('；')};Game.evidence(s,'city','第'+a.gameDay+'天建设收益：'+details.map(d=>d.id+'预算'+d.budget+'，材料'+d.factors.join('/')).join('；'),'observed_action','during',false);return entry;}
const api={blueprints,factors,init,gameDay,cycledToday,draw,build,refit,market,returns,draft,settle};if(typeof module!=='undefined')module.exports=api;else root.GameCity=api;
})(typeof window==='undefined'?globalThis:window);
